const tickets = [
{id:"T1",text:"The app crashes every time I upload a PNG larger than 5MB.",kind:"bug"},
{id:"T2",text:"Please add a dark mode to the dashboard.",kind:"feature"},
{id:"T3",text:"How do I export my invoices as CSV?",kind:"question"},
{id:"T4",text:"Checkout returns HTTP 500 when the cart has more than 20 items.",kind:"bug"},
{id:"T5",text:"It would be great to have SSO with Okta.",kind:"feature"},
{id:"T6",text:"Where can I change my notification email?",kind:"question"}];
const agent = {bug:"bug-fixer",feature:"feature-analyst",question:"support-agent"};
const ask = {bug:"Propose the likely cause and next step.",feature:"Evaluate effort and impact.",question:"Answer the how-to question."};
const results = await Promise.all(tickets.map(async t => {
  const r = await task({
    description: "Support ticket " + t.id + ": \"" + t.text + "\". " + ask[t.kind] + " Reply with a single concise sentence.",
    subagentType: agent[t.kind],
    label: t.id + " -> " + agent[t.kind],
    responseSchema:{type:"object",properties:{outcome:{type:"string"}},required:["outcome"]}
  });
  return {id:t.id, kind:t.kind, agent:agent[t.kind], outcome:r.outcome};
}));
results

